-- Read-only export for the NPC items' content: the click spells of the placeable NPC items (items with a respawn
-- interval in their housing tail), EQEmu's horses table, the familiar pets those spells name with their NPC types, and every
-- NPC spawned in the Guild Lobby and the classic Guild Hall (candidates for the guild service items). 186 spells.
SELECT 'spell' AS result, id, name, teleport_zone, effectid1, effectid2, effectid3, effectid4, effectid5, effectid6, effectid7, effectid8, effectid9, effectid10, effectid11, effectid12, effect_base_value1, effect_base_value2, effect_base_value3, effect_base_value4, effect_base_value5, effect_base_value6, effect_base_value7, effect_base_value8, effect_base_value9, effect_base_value10, effect_base_value11, effect_base_value12 FROM spells_new WHERE id IN (2862, 2863, 2864, 2865, 2867, 2868, 2869, 2870, 2871, 2872, 2873, 2916, 2917, 2918, 2919, 2920, 2921, 2922, 3813, 3814, 3815, 3816, 3818, 3819, 3820, 3821, 3822, 3823, 3824, 3825, 3826, 3828, 3829, 3830, 3831, 8355, 8909, 8910, 8914, 8915, 8916, 8919, 8990, 9111, 9185, 9395, 9397, 9399, 9401, 9696, 9886, 10826, 11502, 11508, 11517, 11518, 11573, 11743, 12327, 12340, 12342, 12449, 12451, 12870, 12881, 12882, 12883, 12884, 12885, 12886, 12891, 12893, 12894, 12895, 12896, 12911, 12912, 12913, 12914, 12915, 12916, 12917, 12935, 12936, 12937, 12938, 12939, 13091, 13092, 13370, 13380, 13381, 13382, 13383, 13384, 13391, 13392, 13396, 15896, 15898, 16532, 16898, 16905, 16914, 16915, 17846, 17849, 17850, 19954, 19999, 20112, 20115, 20119, 20140, 20141, 20153, 20154, 20155, 20169, 20575, 20580, 20584, 20744, 20745, 21057, 21058, 21366, 21376, 21377, 21380, 21381, 21382, 21383, 21508, 21509, 21621, 21622, 21623, 21627, 21639, 21640, 21650, 21930, 21931, 21932, 21933, 21955, 21956, 21957, 22473, 22474, 22475, 23014, 23467, 23469, 23471, 23473, 23475, 23489, 24056, 24057, 24058, 24065, 24073, 24169, 24174, 24179, 24184, 24189, 27380, 27789, 27790, 27791, 27852, 27855, 32045, 32047, 32051, 32053, 32055, 32059, 32061, 32065, 32067, 32882, 32884) ORDER BY id;
SELECT 'horse' AS result, id, filename, race, gender, texture, helmtexture, mountspeed FROM horses ORDER BY id;
SELECT 'familiar' AS result, s.id AS spell_id, p.type, p.npcID, n.name, n.race, n.gender, n.texture, n.helmtexture, n.size, n.bodytype
  FROM spells_new s JOIN pets p ON p.type = s.teleport_zone JOIN npc_types n ON n.id = p.npcID WHERE s.id IN (2862, 2863, 2864, 2865, 2867, 2868, 2869, 2870, 2871, 2872, 2873, 2916, 2917, 2918, 2919, 2920, 2921, 2922, 3813, 3814, 3815, 3816, 3818, 3819, 3820, 3821, 3822, 3823, 3824, 3825, 3826, 3828, 3829, 3830, 3831, 8355, 8909, 8910, 8914, 8915, 8916, 8919, 8990, 9111, 9185, 9395, 9397, 9399, 9401, 9696, 9886, 10826, 11502, 11508, 11517, 11518, 11573, 11743, 12327, 12340, 12342, 12449, 12451, 12870, 12881, 12882, 12883, 12884, 12885, 12886, 12891, 12893, 12894, 12895, 12896, 12911, 12912, 12913, 12914, 12915, 12916, 12917, 12935, 12936, 12937, 12938, 12939, 13091, 13092, 13370, 13380, 13381, 13382, 13383, 13384, 13391, 13392, 13396, 15896, 15898, 16532, 16898, 16905, 16914, 16915, 17846, 17849, 17850, 19954, 19999, 20112, 20115, 20119, 20140, 20141, 20153, 20154, 20155, 20169, 20575, 20580, 20584, 20744, 20745, 21057, 21058, 21366, 21376, 21377, 21380, 21381, 21382, 21383, 21508, 21509, 21621, 21622, 21623, 21627, 21639, 21640, 21650, 21930, 21931, 21932, 21933, 21955, 21956, 21957, 22473, 22474, 22475, 23014, 23467, 23469, 23471, 23473, 23475, 23489, 24056, 24057, 24058, 24065, 24073, 24169, 24174, 24179, 24184, 24189, 27380, 27789, 27790, 27791, 27852, 27855, 32045, 32047, 32051, 32053, 32055, 32059, 32061, 32065, 32067, 32882, 32884) ORDER BY s.id;
SELECT DISTINCT 'guildNpc' AS result, s.zone, n.id, n.name, n.lastname, n.`class`, n.level, n.race, n.gender, n.texture, n.helmtexture, n.size, n.merchant_id
  FROM npc_types n JOIN spawnentry se ON se.npcID = n.id JOIN spawn2 s ON s.spawngroupID = se.spawngroupID WHERE s.zone IN ('guildlobby', 'guildhall') ORDER BY s.zone, n.id;
